from score import *
def alternate(n):
    ref=read_wav(ROOT/'testdata/corpus'/f'{n}.wav')
    row={'base':json.loads((OUT/'pilot.json').read_text())['files'][n]['base']}
    for encoder in ['ours','reference']:
        frames=ROOT/'build/audio-quality-followup/imbe'/f'{n}.{encoder}.imbe'
        data=OUT/f'{n}.via_{encoder}.dvsi'; audio=OUT/f'{n}.via_{encoder}.wav'
        run(BASE,'transcode','--from','imbe7200','--to','dstar',frames,data)
        run(BASE,'decode','--rate','dstar',data,audio)
        row[encoder]={**score(ref,read_wav(audio),None),'input_frames_sha256':hashlib.sha256(frames.read_bytes()).hexdigest()}
    return n,row
if __name__=='__main__':
    rows={}
    with ProcessPoolExecutor(max_workers=4) as pool:
        for job in as_completed([pool.submit(alternate,n) for n in PILOT]):
            n,row=job.result();rows[n]=row
            print(n,{m:round(row[m]['pesq']-row['base']['pesq'],3) for m in ['ours','reference']},flush=True)
    report={'files':rows,'summary':summaries(rows,['ours','reference'])}
    (OUT/'alternate-frontend.json').write_text(json.dumps(report,indent=2))
    print(json.dumps(report['summary'],indent=2))

