from score import *
CHIP=ROOT/'build/vs2026/tools/ambe3000/Release/ambe3000.exe'
if __name__=='__main__':
    input_dir=OUT/'heldout'; names=[r['name'] for r in json.loads((input_dir/'index.json').read_text())['files']]
    identity=subprocess.run([str(CHIP),'--port','COM3','identify'],capture_output=True,text=True,check=True).stdout
    report={'identity':identity,'files':{},'summary':{}}
    for n in names:
        ref=read_wav(input_dir/f'{n}.wav'); row={}
        for tag in ['base','soft_voicing']:
            frames=OUT/f'{n}.{tag}.dvsi';audio=OUT/f'{n}.{tag}.hardware.wav'
            run(CHIP,'--port','COM3','--rate','dstar','decode',frames,audio)
            row[tag]={**score(ref,read_wav(audio),None),'frames_sha256':hashlib.sha256(frames.read_bytes()).hexdigest(),'audio_sha256':hashlib.sha256(audio.read_bytes()).hexdigest()}
        report['files'][n]=row;report['summary']=summaries(report['files'],['soft_voicing'])
        (OUT/'hardware-heldout.json').write_text(json.dumps(report,indent=2))
        print(n,round(row['soft_voicing']['pesq']-row['base']['pesq'],3),flush=True)
    print(json.dumps(report['summary'],indent=2))

